//! `PrimitivePipeline` worker wire format against the pinned CesiumJS cases in
//! `tests/data/scene-primitive-pipeline.json` (generated by
//! `tools/cesium/generate-scene-primitive-pipeline.mjs`).

use cesium_rs::core::*;
use cesium_rs::scene::primitive_pipeline::{CombineGeometryParameters, CombineGeometryResults, PrimitivePipeline};
use cesium_rs::workers::{CombineGeometryResult, PackedGeometryResults};
use serde_json::Value;

fn fixture() -> Value {
    serde_json::from_str(include_str!("data/scene-primitive-pipeline.json")).unwrap()
}

fn number(v: &Value) -> f64 {
    match v {
        Value::String(s) => match s.as_str() {
            "NaN" => f64::NAN,
            "Infinity" => f64::INFINITY,
            "-Infinity" => f64::NEG_INFINITY,
            "-0" => -0.0,
            other => panic!("unexpected number {other}"),
        },
        other => other.as_f64().unwrap(),
    }
}

fn numbers(v: &Value) -> Vec<f64> {
    v.as_array().unwrap().iter().map(number).collect()
}

fn matrix(v: &Value) -> Matrix4 {
    Matrix4(numbers(v).try_into().unwrap())
}

fn radii(v: &Value) -> Cartesian3 {
    let r = numbers(v);
    Cartesian3::new(r[0], r[1], r[2])
}

fn flag(v: &Value, key: &str) -> bool {
    v[key].as_bool().unwrap()
}

/// Compares optional spheres bit-exactly against `[x, y, z, r]` or `null`.
fn assert_spheres(actual: &[Option<BoundingSphere>], expected: &Value, context: &str) {
    let expected = expected.as_array().unwrap();
    assert_eq!(actual.len(), expected.len(), "{context}: sphere count");
    for (i, (a, e)) in actual.iter().zip(expected).enumerate() {
        assert_sphere(a, e, &format!("{context} sphere {i}"));
    }
}

fn assert_sphere(actual: &Option<BoundingSphere>, expected: &Value, context: &str) {
    match (actual, expected) {
        (None, Value::Null) => {}
        (Some(s), e) if !e.is_null() => {
            assert_bits(&[s.center.x, s.center.y, s.center.z, s.radius], &numbers(e), context)
        }
        _ => panic!("{context}: {actual:?} != {expected}"),
    }
}

fn assert_bits(actual: &[f64], expected: &[f64], context: &str) {
    assert_eq!(actual.len(), expected.len(), "{context}: length");
    for (i, (a, e)) in actual.iter().zip(expected).enumerate() {
        assert_eq!(a.to_bits(), e.to_bits(), "{context}[{i}]: {a} != {e}");
    }
}

fn input_parameters(input: &Value) -> CombineGeometryParameters {
    let instances = input["instances"]
        .as_array()
        .unwrap()
        .iter()
        .map(|spec| GeometryInstance {
            geometry: None,
            model_matrix: matrix(&spec["modelMatrix"]),
            id: None,
            attributes: match &spec["offset"] {
                Value::Null => vec![],
                offset => {
                    let o = numbers(offset);
                    vec![(
                        "offset".into(),
                        OffsetGeometryInstanceAttribute { value: [o[0] as f32, o[1] as f32, o[2] as f32] }.into(),
                    )]
                }
            },
            west_hemisphere_geometry: None,
            east_hemisphere_geometry: None,
        })
        .collect();
    CombineGeometryParameters {
        instances,
        ellipsoid_radii: radii(&input["ellipsoid"]),
        is_geographic: flag(input, "isGeographic"),
        uint_index_support: flag(input, "elementIndexUintSupported"),
        scene_3d_only: flag(input, "scene3DOnly"),
        vertex_cache_optimize: flag(input, "vertexCacheOptimize"),
        compress_vertices: flag(input, "compressVertices"),
        model_matrix: matrix(&input["modelMatrix"]),
        create_pick_offsets: flag(input, "createPickOffsets"),
    }
}

fn create_results(input: &Value) -> Vec<PackedGeometryResults> {
    input["createGeometryResults"]
        .as_array()
        .unwrap()
        .iter()
        .map(|r| PackedGeometryResults {
            string_table: r["stringTable"].as_array().unwrap().iter().map(|s| s.as_str().unwrap().into()).collect(),
            packed_data: numbers(&r["packedData"]),
        })
        .collect()
}

#[test]
fn combine_geometry_parameters_match_reference() {
    let fixture = fixture();
    let cases = fixture["parameters"].as_array().unwrap();
    assert_eq!(cases.len(), 6);
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let input = &case["input"];
        let parameters = input_parameters(input);
        let packed = PrimitivePipeline::pack_combine_geometry_parameters(&parameters, create_results(input));
        assert_bits(&packed.packed_instances, &numbers(&case["packed"]["packedInstances"]), name);
        assert_eq!(packed.is_geographic, flag(&case["packed"], "isGeographic"), "{name}");
        assert_eq!(packed.create_geometry_results, create_results(input), "{name}: geometry results pass through");

        let expected = &case["unpacked"];
        let unpacked = PrimitivePipeline::unpack_combine_geometry_parameters(&packed);
        if expected.get("throws").is_some() {
            assert!(unpacked.is_err(), "{name}: Cesium throws {}", expected["throws"]);
            continue;
        }
        let unpacked = unpacked.unwrap_or_else(|e| panic!("{name}: {e}"));
        let instances = expected["instances"].as_array().unwrap();
        assert_eq!(unpacked.instances.len(), instances.len(), "{name}: instances");
        for (i, (actual, expected)) in unpacked.instances.iter().zip(instances).enumerate() {
            let context = format!("{name} instance {i}");
            assert_bits(&actual.model_matrix.0, &numbers(&expected["modelMatrix"]), &context);
            let offset = actual.attributes.iter().find(|(n, _)| n == "offset").map(|(_, a)| a.value.to_f64_vec());
            match &expected["offset"] {
                Value::Null => assert!(offset.is_none(), "{context}: offset"),
                o => assert_bits(&offset.expect("offset attribute"), &numbers(o), &context),
            }
            match (&actual.geometry, &expected["geometry"]) {
                (None, Value::Null) => {}
                (Some(g), e) if !e.is_null() => assert_sphere(&g.bounding_sphere, e, &context),
                (g, e) => panic!("{context}: geometry {} != {e}", g.is_some()),
            }
        }
        assert_bits(
            &[unpacked.ellipsoid_radii.x, unpacked.ellipsoid_radii.y, unpacked.ellipsoid_radii.z],
            &numbers(&expected["ellipsoid"]),
            name,
        );
        assert_eq!(unpacked.is_geographic, flag(expected, "isGeographic"), "{name}");
        assert_eq!(unpacked.uint_index_support, flag(expected, "elementIndexUintSupported"), "{name}");
        assert_eq!(unpacked.scene_3d_only, flag(expected, "scene3DOnly"), "{name}");
        assert_eq!(unpacked.vertex_cache_optimize, flag(expected, "vertexCacheOptimize"), "{name}");
        assert_eq!(unpacked.compress_vertices, flag(expected, "compressVertices"), "{name}");
        assert_eq!(unpacked.create_pick_offsets, flag(expected, "createPickOffsets"), "{name}");
        assert_bits(&unpacked.model_matrix.0, &numbers(&expected["modelMatrix"]), name);
    }
}

fn spheres(v: &Value) -> Vec<Option<BoundingSphere>> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|s| match s {
            Value::Null => None,
            s => {
                let s = numbers(s);
                Some(BoundingSphere::new(Cartesian3::new(s[0], s[1], s[2]), s[3]))
            }
        })
        .collect()
}

#[test]
fn combine_geometry_results_match_reference() {
    let fixture = fixture();
    let cases = fixture["results"].as_array().unwrap();
    assert_eq!(cases.len(), 3);
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let input = &case["input"];
        let results = CombineGeometryResults {
            geometries: None,
            model_matrix: Matrix4::IDENTITY,
            attribute_locations: Some(vec![("position".into(), 0)]),
            pick_offsets: None,
            offset_instance_extend: None,
            bounding_spheres: spheres(&input["boundingSpheres"]),
            bounding_spheres_cv: spheres(&input["boundingSpheresCV"]),
        };
        let packed = PrimitivePipeline::pack_combine_geometry_results(results);
        let widen = |v: &[f32]| v.iter().map(|&x| f64::from(x)).collect::<Vec<_>>();
        assert_bits(&widen(&packed.bounding_spheres), &numbers(&case["packed"]["boundingSpheres"]), name);
        assert_bits(&widen(&packed.bounding_spheres_cv), &numbers(&case["packed"]["boundingSpheresCV"]), name);

        let unpacked = PrimitivePipeline::unpack_combine_geometry_results(packed).unwrap();
        assert_spheres(&unpacked.bounding_spheres, &case["unpacked"]["boundingSpheres"], name);
        assert_spheres(&unpacked.bounding_spheres_cv, &case["unpacked"]["boundingSpheresCV"], name);
        assert_eq!(unpacked.attribute_locations, Some(vec![("position".into(), 0)]), "{name}: passes through");
    }
}

#[test]
fn unpack_combine_geometry_results_rejects_malformed_sphere_buffers() {
    let result = |spheres: Vec<f32>| CombineGeometryResult {
        geometries: None,
        model_matrix: Matrix4::IDENTITY,
        attribute_locations: None,
        pick_offsets: None,
        offset_instance_extend: None,
        bounding_spheres: spheres,
        bounding_spheres_cv: vec![0.],
    };
    for malformed in [vec![], vec![1., 1., 0., 0.], vec![2., 1., 0., 0., 0., 1.]] {
        assert!(
            PrimitivePipeline::unpack_combine_geometry_results(result(malformed.clone())).is_err(),
            "{malformed:?}"
        );
    }
    // Only a flag of exactly 1.0 is a sphere, as in `unpackBoundingSpheres`.
    let unpacked = PrimitivePipeline::unpack_combine_geometry_results(result(vec![1., 0.5, 1., 2., 3., 4.])).unwrap();
    assert_eq!(unpacked.bounding_spheres, vec![None]);
}

#[test]
fn create_geometry_results_round_trip() {
    let geometry = BoxGeometry::from_dimensions(Cartesian3::new(1., 2., 3.), VertexFormat::POSITION_ONLY, None)
        .and_then(|b| b.create_geometry())
        .unwrap();
    let packed = PrimitivePipeline::pack_create_geometry_results(&[Some(geometry.clone()), None]);
    let unpacked = PrimitivePipeline::unpack_create_geometry_results(&packed).unwrap();
    assert_eq!(unpacked.len(), 2);
    assert!(unpacked[1].is_none());
    let round = unpacked[0].as_ref().unwrap();
    assert_eq!(round.bounding_sphere, geometry.bounding_sphere);
    assert_eq!(round.indices.as_ref().map(|i| i.to_f64_vec()), geometry.indices.as_ref().map(|i| i.to_f64_vec()));
}
